// WIZARD — a stick-figure wizard with one book and a fireball that never goes out (until he throws it).
//   STRIKE   (attack)          book bonk. Forward swings the book out ahead; up/down the fireball hand swats.
//   GIMMICK  (special)         FIREBALL: hold to grow, sideways flies flat, down leaves a fire patch. Then the hand is empty until it relights.
//   RECOVERY (up + special)    the fireball rockets overhead and hauls him up by the arm.
//   GRAB     (grab)            the book snaps shut on them.
// The drawings face right with the book held BEHIND him and the fireball in front, so forward book strikes
// flip the atk-fwd cell (book leads) and bair uses it unflipped (book already behind).
export default function make(api) {
  const { hb, cap, key, mv, throwMove, spawnProjectile, spriteAnims, spriteLoops, tripped, B } = api;

  const stats = {
    weight: 70, walk: 2.3, run: 4.4, dashInit: 5.2, airSpeed: 3.6, airAccel: 0.18,
    fallSpeed: 5.0, fastFall: 8.5, gravity: 0.33, shortHop: 7, fullHop: 11.5, doubleJump: 11,
    jumps: 2, wallJump: false, traction: 0.45, height: 104, width: 52, crouchHeight: 72, landLag: 5, ledgeReach: 36,
  };

  const P = (extra) => ({ ...extra });
  const rest = P({});
  const strikePoses = (total, hit, lean, extra = {}) => [
    key(0, P({ rot: -lean * 0.5, sx: 0.96, sy: 1.04, ...extra })),
    key(hit, P({ rot: lean, sx: 1.1, sy: 0.94, ...extra })),
    key(Math.min(total - 1, hit + 6), P({ rot: lean * 0.8, sx: 1.04, sy: 0.98, ...extra })),
    key(total, rest),
  ];
  const BOOK = { fx: "heavy" };
  const FIRE = { fx: "flame" };
  const looks = {
    fireball: { cell: "idle", crop: [294, 146, 76, 144], trail: "smoke", color: "#ff7a1a" },
    patch: { shape: "puddle", color: "#ff5a1f", ink: "#c21a10", texture: "flame" },
    flame: { shape: "blob", color: "#ff8c1a", ink: "#d42a12", texture: "flame" },
  };

  // THE STRIKE: forward/back is the book on the straight arm (short reach); up/down is the fireball hand as drawn.
  const STRIKE = { total: 28, hit: 7, active: 4, damage: 10, r: 16 };
  const aim = (id, dir, opts = {}) => {
    const s = { ...STRIKE, ...opts };
    const start = dir === "u" ? [6, -64] : dir === "b" ? [-14, -38] : dir === "d" ? [14, -26] : [14, -38];
    const end = dir === "u" ? [22, -94] : dir === "b" ? [-46, -50] : dir === "d" ? [32, -14] : [46, -50];
    const angle = dir === "u" ? 88 : dir === "d" ? 30 : dir === "b" ? 40 : 38;
    const lean = dir === "u" ? -6 : dir === "b" ? -16 : dir === "d" ? 10 : 14;
    const extra = dir === "d" ? { sy: 0.9, dy: 6 } : dir === "u" ? { dy: -4, sy: 1.06 } : {};
    const cell = dir === "u" ? "atk-up" : dir === "d" ? "atk-down" : "atk-fwd";
    const look = dir === "u" || dir === "d" ? FIRE : BOOK;
    return mv(id, s.total, [cap([s.hit, s.hit + s.active - 1], start[0], start[1], end[0], end[1], s.r, s.damage, angle, s.base ?? 38, s.growth ?? 80, { ...look, ...(s.hb ?? {}) })],
      strikePoses(s.total, s.hit, lean, extra), { cell, cellFlip: dir === "f", ...(s.mv ?? {}) });
  };
  const GRAB = { total: 36, hit: 8, damage: 8 };
  const toss = (id, angle, base, growth, pose) => throwMove(id, 32, 14, GRAB.damage, angle, base, growth, [key(0, P({ rot: 6 })), key(14, P(pose)), key(32, rest)]);

  const EMPTY = 150;
  const moves = {
    jab1: aim("jab1", "f", { total: 22, hit: 5, damage: 6, mv: { iasa: 16 } }),
    ftilt: aim("ftilt", "f"),
    dashAttack: aim("dashAttack", "f", { total: 36, hit: 8, damage: 10, mv: { motion: [[1, 5.5, 0], [10, 3, 0], [18, 1, 0]] } }),
    nair: aim("nair", "f", { total: 28, hit: 6, damage: 8, mv: { aerial: true, landingLag: 9 } }),
    fair: aim("fair", "f", { damage: 11, mv: { aerial: true, landingLag: 11 } }),
    bair: aim("bair", "b", { damage: 12, mv: { aerial: true, landingLag: 12 } }),
    utilt: aim("utilt", "u", { damage: 9 }),
    uair: aim("uair", "u", { damage: 10, mv: { aerial: true, landingLag: 10 } }),
    dtilt: aim("dtilt", "d", { damage: 8 }),
    dair: aim("dair", "d", { total: 38, hit: 11, damage: 12, hb: { spike: true }, mv: { aerial: true, landingLag: 16 } }),
    // the charged strike: the book comes down hard
    fsmash: mv("fsmash", 50, [
      cap([15, 18], 18, -46, 50, -52, 20, 18, 40, 46, 100, { fx: "tip", priority: 0 }),
      cap([15, 20], 4, -40, 30, -46, 16, 14, 40, 40, 84, { ...BOOK, priority: 1 }),
    ], strikePoses(50, 15, 22, { dy: 2 }), { smash: true, cell: "atk-fwd", cellFlip: true }),
    usmash: aim("usmash", "u", { total: 48, hit: 14, active: 6, damage: 16, r: 22, base: 42, growth: 98, mv: { smash: true } }),
    dsmash: mv("dsmash", 52, [
      cap([15, 18], 12, -24, 36, -14, 20, 15, 30, 44, 88, { ...FIRE, group: 0 }),
      cap([21, 24], -18, -50, -40, -30, 20, 15, 30, 44, 88, { ...BOOK, group: 1 }),
    ], [key(0, P({ sy: 0.92 })), key(15, P({ rot: 16, sx: 1.12, sy: 0.84 })), key(21, P({ rot: -16, sx: 1.12, sy: 0.84 })), key(52, rest)], { smash: true, cell: "atk-down" }),
    // grab: the book, held up front, snaps shut on them
    grab: mv("grab", GRAB.total, [hb([GRAB.hit, GRAB.hit + 2], 34, -50, 24, 0, 0, 0, 0, { grab: true })], strikePoses(GRAB.total, GRAB.hit, 10), { isGrab: true, cell: "block" }),
    dashGrab: mv("dashGrab", 42, [hb([10, 12], 44, -50, 26, 0, 0, 0, 0, { grab: true })], strikePoses(42, 10, 18), { isGrab: true, cell: "block", motion: [[1, 4.5, 0], [10, 0, 0]] }),
    pummel: mv("pummel", 16, [], [key(0, P({ rot: 6 })), key(6, P({ rot: 14, sx: 1.06 })), key(16, P({ rot: 6 }))], { cell: "block" }),
    fthrow: toss("fthrow", 42, 58, 70, { rot: 24, sx: 1.1 }),
    bthrow: toss("bthrow", 40, 62, 78, { rot: -36 }),
    uthrow: toss("uthrow", 90, 70, 90, { dy: -12, sy: 1.14 }),
    dthrow: toss("dthrow", 70, 45, 40, { sy: 0.82, sx: 1.14, dy: 12 }),
    // GIMMICK, FIREBALL: hold to grow, a slow fat lob
    nspecial: mv("nspecial", 46, [], [key(0, P({ rot: -8, sy: 1.04 })), key(20, P({ rot: -12, sx: 0.94, sy: 1.08 })), key(22, P({ rot: 14, sx: 1.1, sy: 0.94 })), key(46, rest)], { hook: "hurl", cell: "atk-fwd" }),
    // sideways: flat and far
    sspecial: mv("sspecial", 42, [], strikePoses(42, 14, 16), { hook: "fling", cell: "atk-fwd" }),
    // down: dropped at his feet as a little fire patch
    dspecial: mv("dspecial", 40, [], [key(0, rest), key(12, P({ rot: 10, sy: 0.88, dy: 4 })), key(40, rest)], { hook: "drop", cell: "atk-down" }),
    // RECOVERY: the fireball rockets upward, singing anyone above
    uspecial: mv("uspecial", 56, [cap([4, 28], 10, -84, 24, -104, 24, 6, 85, 40, 60, { ...FIRE, rehit: 8 })], [key(0, P({ sy: 0.88, sx: 1.1 })), key(4, P({ sy: 1.16, sx: 0.9 })), key(30, P({ rot: 6, sy: 1.08 })), key(56, P({ rot: -8 }))], { hook: "lift", helpless: true, ledgeOk: true, cell: "jump" }),
    ledgeAttack: aim("ledgeAttack", "f", { total: 38, hit: 11, damage: 8 }),
    getupAttack: mv("getupAttack", 44, [cap([12, 15], 10, -30, 44, -46, 18, 7, 45, 40, 60, { ...BOOK, group: 0 }), cap([20, 23], -10, -30, -44, -46, 18, 7, 45, 40, 60, { ...BOOK, group: 1 })], [key(0, rest), key(12, P({ rot: 14 })), key(20, P({ rot: -14 })), key(44, rest)], { cell: "atk-fwd" }),
    taunt: mv("taunt", 50, [], [key(0, rest), key(14, P({ sy: 1.12, dy: -4 })), key(28, P({ sy: 0.94 })), key(50, rest)], { cell: "atk-up" }),
  };

  // the fireball leaves the forward hand (atk-fwd cell, ~36 units ahead, ~50 up)
  const throwBall = (state, f, vx, vy, g, life, r, damage, base, growth) => {
    spawnProjectile(state, f, "fireball", f.x + f.moveFacing * 36, f.y - 50, f.moveFacing * vx, vy, life,
      { frames: [0, 999], x: 0, y: 0, r, damage, angle: 40, base, growth, fx: "flame" }, { g });
    f.bars.flame = 0;
  };

  return {
    id: "wizard",
    name: "WIZARD",
    tagline: "Read one book. Set everything on fire.",
    stats,
    moves,
    rig: { anims: spriteAnims(), loops: spriteLoops },
    palette: { colors: { marker: "#2a78d8" }, outline: "#1c1c1c" },
    looks,
    special: () => ({ charge: 0 }),
    // the flame goes out on a cast and is back once it has burned all the way up again
    bars: { flame: { label: "FLAME", color: "#ff6a1a", max: EMPTY, start: EMPTY, trip: 0, rearm: EMPTY } },
    hooks: {
      hurl: ({ state, f, input }) => {
        if (f.frame <= 20 && !tripped(f, "flame") && f.special.charge < 60 && (input.b & B.SPECIAL)) {
          f.special.charge++;
          if (f.frame === 20) f.frame = 19;
          return;
        }
        if (f.frame === 22) {
          if (!tripped(f, "flame")) {
            const c = f.special.charge / 60;
            throwBall(state, f, 4.5, -1.2, 0.06, 110, 18 + c * 14, 9 + c * 9, 40 + c * 22, 70 + c * 30);
          }
          f.special.charge = 0;
        }
      },
      fling: ({ state, f }) => {
        if (f.frame === 14 && !tripped(f, "flame")) throwBall(state, f, 7, 0, 0, 90, 16, 10, 40, 72);
      },
      drop: ({ state, f }) => {
        if (f.frame === 12 && !tripped(f, "flame")) {
          spawnProjectile(state, f, "patch", f.x + f.moveFacing * 28, f.y - 6, 0, 0, 120,
            { frames: [0, 999], x: 0, y: 0, r: 22, damage: 4, angle: 80, base: 30, growth: 30, rehit: 20 }, { g: 0 });
          f.bars.flame = 0;
        }
      },
      lift: ({ f, input }) => {
        if (f.frame === 4) { f.grounded = false; f.platform = -1; f.usedUpSpecial = true; }
        if (f.frame >= 4 && f.frame <= 32) {
          f.vy = -7.6 + (f.frame - 4) * 0.15;
          f.vx = (input.x / 100) * 4.8;
        }
      },
    },
    onFrame: ({ f }) => { f.bars.flame++; },
    visual: (f) => ({ glow: tripped(f, "flame") ? 0 : 0.3 + f.special.charge / 120 }),
  };
}
